import { useState, useEffect } from 'react';
import { addMisc, getMiscByKey } from 'dataAccess'

export function usePWAStatus() {
  const [isInstalled, setIsInstalled] = useState(false);
  const [isPWA, setIsPWA] = useState(false);
  const [isSupported, setIsSupported] = useState(false);
  const [isChecking, setIsChecking] = useState(true);

  const saveInstallStatus = async () => {
    getMiscByKey('installed').then(installed => {
      console.log("getMiscByKey res");
      console.dir(installed);
      const isInstalled = installed ? installed.value : false;
      if (!isInstalled) {
        addMisc("installed", false)
      }
      setIsInstalled(isInstalled)
    })
  }

  const checkPWAStatus = async () => {
    saveInstallStatus();
    let installed = false;
    let supported = false;

    const isStandalone =
      window.matchMedia('(display-mode: standalone)').matches ||
      window.navigator.standalone === true;

    installed = isStandalone;
    setIsPWA(isStandalone);

    console.log("usaPwaStatus running as PWA: ", installed);

    // Check if getInstalledRelatedApps is supported
    if ('getInstalledRelatedApps' in navigator) {
      supported = true;
      try {
        const relatedApps = await navigator.getInstalledRelatedApps();
        const pwaApp = relatedApps.find(
          (app) =>
            app.platform === 'webapp' &&
            app.url === window.location.origin + '/manifest.webmanifest'
        );
        if (pwaApp) {
          installed = true;
        }
      } catch (error) {
        console.error('Error fetching related apps:', error);
        const event = new CustomEvent('logImportantMessage');
        event.log = `Error fetching related apps: ${JSON.stringify(error)}`
        window.dispatchEvent(event);
      }
    }

    let pwaDetected = false;

    // 1. Check display-mode
    if (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches) {
      pwaDetected = true;
    }

    // 2. Check navigator.standalone (iOS)
    if (navigator.standalone) {
      pwaDetected = true;
    }

    // 3. Check if the route set a session variable
    if (sessionStorage.getItem('pwaLaunch') === 'true') {
      pwaDetected = true;
    }

    if (sessionStorage.getItem('pwaLaunch') === 'true') {
      pwaDetected = true;
    }

    function getDisplayMode() {
      if (window.matchMedia('(display-mode: fullscreen)').matches) {
        return 'fullscreen';
      } else if (window.matchMedia('(display-mode: standalone)').matches) {
        return 'standalone';
      } else if (window.matchMedia('(display-mode: minimal-ui)').matches) {
        return 'minimal-ui';
      } else if (window.matchMedia('(display-mode: browser)').matches) {
        return 'browser';
      } else if (window.matchMedia('(display-mode: picture-in-picture)').matches) {
        return 'picture-in-picture';
      }  else if (window.matchMedia('(display-mode: window-controls-overlay)').matches) {
        return 'window-controls-overlay';
      } else {
        return 'unknown';
      }
    }

    const e1 = new CustomEvent('logMessage');
    e1.log = `getPWADisplayMode document.referrer: ${document.referrer} ;;; getDisplayMode: ${getDisplayMode()} ;;; navigator.standalone: ${navigator.standalone}`
    window.dispatchEvent(e1);


    setIsPWA(pwaDetected);
    const e2 = new CustomEvent('logMessage');
    e2.log = `setIsPWA pwaDetected: ${pwaDetected}`
    window.dispatchEvent(e2);

    const e3 = new CustomEvent('logMessage');
    e3.log = `sessionStorage.getItem('pwaLaunch'): ${sessionStorage.getItem('pwaLaunch')}`
    window.dispatchEvent(e3);

    navigator.getInstalledRelatedApps().then((res) => {
      const e4 = new CustomEvent('logMessage');
      e4.log = `navigator.getInstalledRelatedApps(): ${res}`;
      window.dispatchEvent(e4);
    });

    const e5 = new CustomEvent('logMessage');
    e5.log = `JSON.stringify(navigator): ${JSON.stringify(navigator)}`
    window.dispatchEvent(e5);



    const event = new CustomEvent('logMessage');
    event.log = `checkPWAStatus supported, installed: ${supported} ${installed}`
    window.dispatchEvent(event);
    return {supported, installed}
  };

  useEffect(() => {
    let isMounted = true;



    checkPWAStatus().then((res) => {
      if (isMounted) {
        const { supported, installed } = res;
        console.dir({ supported, installed })
        const event = new CustomEvent('logMessage');
        event.log = `checkPWAStatus then res: ${JSON.stringify(res)}`
        window.dispatchEvent(event);
        setIsSupported(supported);
        setIsInstalled(installed);
        setIsChecking(false);
      }
    });

    const handleAppInstalled = () => {
      console.log('App was installed');
      const event = new CustomEvent('logMessage');
        event.log = `App was installed`
        window.dispatchEvent(event);
      // localStorage.setItem('pwaInstalled', 'yes');
      addMisc("installed", true);
      setIsInstalled(true);
    };

    const handleDisplayModeChange = () => {
      const isStandalone =
        window.matchMedia('(display-mode: standalone)').matches ||
        window.navigator.standalone === true;
      setIsPWA(isStandalone);
      if (isStandalone) {
        setIsInstalled(true);
      }
    };

    window.addEventListener('appinstalled', handleAppInstalled);
    window
      .matchMedia('(display-mode: standalone)')
      .addEventListener('change', handleDisplayModeChange);

    return () => {
      isMounted = false;
      window.removeEventListener('appinstalled', handleAppInstalled);
      window
        .matchMedia('(display-mode: standalone)')
        .removeEventListener('change', handleDisplayModeChange);
    };
  }, []);

  function getPWADisplayMode() {
    const event = new CustomEvent('logMessage');
    event.log = `getPWADisplayMode document.referrer: ${document.referrer} ;;; window.matchMedia: ${window.matchMedia}`
    window.dispatchEvent(event);
    if (document.referrer.startsWith('android-app://'))
      return 'twa';
    if (window.matchMedia('(display-mode: browser)').matches)
      return 'browser';
    if (window.matchMedia('(display-mode: standalone)').matches)
      return 'standalone';
    if (window.matchMedia('(display-mode: minimal-ui)').matches)
      return 'minimal-ui';
    if (window.matchMedia('(display-mode: fullscreen)').matches)
      return 'fullscreen';
    if (window.matchMedia('(display-mode: window-controls-overlay)').matches)
      return 'window-controls-overlay';

    return 'unknown';
  }

  return { isInstalled, isPWA, isSupported, isChecking, setIsPWA, checkPWAStatus, getPWADisplayMode };
}
